@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services

<div class="nav flex-column nav-pills me-3" role="tablist" aria-orientation="vertical">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                type="button"
                role="tab"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>@section
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Profile Settings</h4>

@if (_profile is null)
{
    <p class="text-muted">Loading...</p>
    return;
}

@if (!string.IsNullOrEmpty(_statusMessage))
{
    <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
        @_statusMessage
        <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label fw-semibold">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label fw-semibold">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label fw-semibold">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>
    </div>
    <div class="col-md-4 text-center">
        <div class="mb-3">
            <label class="form-label fw-semibold d-block">Avatar Preview</label>
            <div class="border rounded p-2 d-inline-block mb-2" style="width:130px;height:130px;">
                <img src="@_avatarUrl" alt="Avatar" class="rounded-circle img-fluid"
                     style="width:120px;height:120px;object-fit:cover;"
                     @onerror="() => {}" />
            </div>
            <div class="text-muted small text-truncate" style="max-width:200px;" title="@_avatarUrl">
                @_avatarUrl
            </div>
        </div>
    </div>
</div>

<div class="d-flex gap-2">
    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @if (_saving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Changes
    </button>
    <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
        Discard Changes
    </button>
</div>

@code {
    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private string? _statusMessage;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateFields(_profile);
    }

    private void PopulateFields(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(updated);
            _profile = updated;
            _statusMessage = "Profile saved successfully!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_profile is not null)
        {
            PopulateFields(_profile);
        }
        _statusMessage = null;
    }
}

