{"file_text": "@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading...</p>
    return;
}

@if (!string.IsNullOrEmpty(_statusMessage))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_statusMessage
        <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-7">
        <div class="mb-4">
            <h6 class="fw-semibold mb-2">Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold mb-2">Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold mb-2">Language</h6>
            <select class="form-select" style="max-width:250px;"
                    @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="mb-4">
            <h6 class="fw-semibold mb-2">Compact Mode</h6>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">
                    Reduce spacing and use smaller elements
                </label>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>
    </div>

    <div class="col-md-5">
        <h6 class="fw-semibold mb-2">Preview</h6>
        <div class="border rounded @PreviewClasses" style="@PreviewStyle">
            <div class="@(_compactMode ? "p-2" : "p-3")">
                <h6 style="@FontStyle" class="@PreviewTextClass">Sample Heading</h6>
                <p style="@FontStyle" class="@PreviewTextClass mb-2">
                    This is a preview of your selected appearance settings.
                </p>
                <button class="btn @PreviewBtnClass @(_compactMode ? "btn-sm" : "")">
                    Sample Button
                </button>
                <div class="mt-2">
                    <span class="badge @PreviewBadgeClass">@_language</span>
                    <span class="badge bg-secondary ms-1">@_fontSize</span>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _statusMessage;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            _settings = updated;
            _statusMessage = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }

    private string PreviewClasses => _theme switch
    {
        "Dark" => "bg-dark text-light",
        _ => "bg-light text-dark"
    };

    private string PreviewStyle => _theme switch
    {
        "Dark" => "min-height:180px;",
        _ => "min-height:180px;"
    };

    private string PreviewTextClass => _theme == "Dark" ? "text-light" : "text-dark";

    private string PreviewBtnClass => _theme == "Dark" ? "btn-outline-light" : "btn-outline-dark";

    private string PreviewBadgeClass => _theme == "Dark" ? "bg-info" : "bg-primary";

    private string FontStyle => _fontSize switch
    {
        "Small" => "font-size:0.85rem;",
        "Large" => "font-size:1.15rem;",
        _ => "font-size:1rem;"
    };
}
