@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Notification Preferences</h4>

@if (_prefs is null)
{
    <p class="text-muted">Loading...</p>
    return;
}

@if (!string.IsNullOrEmpty(_statusMessage))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_statusMessage
        <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
    </div>
}

<div class="mb-4">
    <h6 class="fw-semibold mb-3">General</h6>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

<div class="mb-4">
    <h6 class="fw-semibold mb-3">Muted Channels</h6>
    <p class="text-muted small">Uncheck channels you want to receive notifications from.</p>
    @foreach (var channel in _channels)
    {
        <div class="form-check mb-2">
            <input class="form-check-input" type="checkbox" id="@($"ch-{channel.Name}")"
                   checked="@channel.IsMuted"
                   @onchange="e => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
            <label class="form-check-label text-capitalize" for="@($"ch-{channel.Name}")">@channel.Name</label>
        </div>
    }
</div>

<button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
    @if (_saving)
    {
        <span class="spinner-border spinner-border-sm me-1"></span>
    }
    Save Preferences
</button>

@code {
    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];
    private bool _saving;
    private string? _statusMessage;

    private record ChannelState(string Name, bool IsMuted);

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
    }

    private void ToggleChannel(string name, bool isMuted)
    {
        var idx = _channels.FindIndex(c => c.Name == name);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { IsMuted = isMuted };
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        try
        {
            var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
            var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
            await SettingsService.SaveNotificationPrefsAsync(updated);
            _prefs = updated;
            _statusMessage = "Notification preferences saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

