@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services

<h6 class="fw-semibold mb-3">Active Sessions</h6>

@if (Sessions is null || Sessions.Count == 0)
{
    <p class="text-muted">No active sessions.</p>
    return;
}

@if (_confirmingSessionId is not null)
{
    <div class="alert alert-warning d-flex align-items-center gap-2">
        <span>Are you sure you want to revoke this session?</span>
        <button class="btn btn-sm btn-danger" @onclick="ConfirmRevoke">Yes, Revoke</button>
        <button class="btn btn-sm btn-outline-secondary" @onclick="() => _confirmingSessionId = null">Cancel</button>
    </div>
}

<div class="table-responsive">
    <table class="table table-striped table-hover align-middle">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>
                        @session.Device
                        @if (session.Id == CurrentSessionId)
                        {
                            <span class="badge bg-success ms-1">Current</span>
                        }
                    </td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-sm btn-outline-danger"
                                    @onclick="() => _confirmingSessionId = session.Id">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private string? _confirmingSessionId;

    private async Task ConfirmRevoke()
    {
        if (_confirmingSessionId is not null)
        {
            await OnSessionRevoked.InvokeAsync(_confirmingSessionId);
            _confirmingSessionId = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

