@using sv_9231db1e14b545dc901c4f203f8ce8e8.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Security Settings</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading...</p>
    return;
}

@if (!string.IsNullOrEmpty(_statusMessage))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_statusMessage
        <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
    </div>
}

<ChangePasswordPanel OnPasswordChanged="HandlePasswordChange" />

<div class="card mb-3">
    <div class="card-body d-flex justify-content-between align-items-center">
        <div>
            <h6 class="fw-semibold mb-1">Two-Factor Authentication</h6>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="twoFactor"
                   checked="@_twoFactorEnabled"
                   @onchange="e => _twoFactorEnabled = (bool)(e.Value ?? false)" />
        </div>
    </div>
</div>

@if (_settings.LastPasswordChange.HasValue)
{
    <p class="text-muted small mb-4">
        Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
    </p>
}

<ActiveSessionsTable Sessions="_sessions"
                     CurrentSessionId="sess-1"
                     OnSessionRevoked="HandleRevokeSession" />

@code {
    private SecuritySettings? _settings;
    private bool _twoFactorEnabled;
    private List<ActiveSession> _sessions = [];
    private string? _statusMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _sessions = _settings.Sessions.ToList();
    }

    private async Task HandlePasswordChange()
    {
        await SettingsService.ChangePasswordAsync("", "");
        await LoadAsync();
        _statusMessage = "Password changed successfully!";
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        await LoadAsync();
        _statusMessage = "Session revoked.";
    }
}

